            emit_error()

        p = m["path"]
        if not isinstance(p, str):
            emit_error()
        if p.startswith("/"):
            emit_error()
        if "\\" in p:
            emit_error()
        parts = p.split("/")
        for part in parts:
            if part == "" or part == "." or part == "..":
                emit_error()

        cb = m["content_b64"]
        if not isinstance(cb, str):
            emit_error()
        # Strict base64: must be valid chars and proper padding
        if len(cb) % 4 != 0:
            emit_error()
        try:
            content = base64.b64decode(cb, validate=True)
        except Exception:
            emit_error()
        if len(content) > 64 * 1024:
            emit_error()

        mode = m["mode"]
        if isinstance(mode, bool) or not isinstance(mode, int):
            emit_error()
        if mode < 0 or mode > 511:
            emit_error()

    # Build ZIP archive in memory
    date_time = (year, month, day, hour, minute, second)

    buf = bytearray()
    with zipfile.ZipFile(buf, 'w', zipfile.ZIP_DEFLATED) as zf:
        zf.comment = comment.encode('utf-8')

        # Sort members by path in Unicode code-point order
        sorted_members = sorted(members, key=lambda x: x["path"])

        for m in sorted_members:
            p = m["path"]
            content = base64.b64decode(m["content_b64"])
            mode = m["mode"]

            info = zipfile.ZipInfo(p, date_time)
            info.compress_type = zipfile.ZIP_DEFLATED
            info.create_system = 3  # Unix
            info.external_attr = (0o100000 | mode) << 16
            zf.writestr(info, content)

    archive_bytes = bytes(buf)
    archive_b64 = base64.b64encode(archive_bytes).decode('ascii')
    sha256 = hashlib.sha256(archive_bytes).hexdigest()

    result = {
        "format": "zip",
        "archive_b64": archive_b64,
        "sha256": sha256
    }
    sys.stdout.write(json.dumps(result, separators=(',', ':')) + '\n')


if __name__ == '__main__':
    main()
